// Typed access to the pipeline's real outputs in ../../data. Nothing here is generated by the page.
import lincoln from '../../data/run/lincoln.json'
import pelham from '../../data/run/pelham.json'
import westLincoln from '../../data/run/west-lincoln.json'
import saratoga from '../../data/run/saratoga.json'
import warren from '../../data/run/warren.json'
import tompkins from '../../data/run/tompkins.json'
import metaJson from '../../data/run/meta.json'
import scorecardJson from '../../data/scorecard.json'
import seedJson from '../../data/accounts.seed.json'
import keyJson from '../../data/answer_key.json'

export type Cite = {
  quote: string
  source: string
  url: string
  title: string
  pdf_page: number | null
  fetched_at: string
  rows?: number
  year?: string
  sum_mi?: number
  column?: string
}

export type DocLink = { url: string; title: string; fetched_at: string }

export type OptionResult = 'filled' | 'blank' | 'note'
export type QuestionOption = { label: string; value_km: number | null; result: OptionResult; centerline?: boolean }
export type Question = { field: string; kind: 'pick' | 'centerline'; text: string; options: QuestionOption[] }

export type RowStatus = 'filled' | 'needs_human' | 'not_found' | 'merge'

export type Within = { km: number; mi: number; column: string; year: string; note: string }

export type Partial = { km: number; why: string; sources: Cite[] }

export type Merge = {
  action: 'merge'
  contact_id: string
  matched_on: string
  existing: { mock: boolean; id: string; name: string; title: string; phone: string; email: string | null; note: string }
  changes: Record<string, { from: string; to: string }>
}

export type ProposedRow = {
  field: 'road_length_km' | 'email' | 'phone' | 'roads_head' | 'key_documents' | 'brief'
  label: string
  current: string | null
  status: RowStatus
  sources: (Cite | DocLink)[]
  proposed: string | string[] | null
  question?: Question
  within?: Within
  detail?: string
  partial?: Partial[]
  merge?: Merge
}

export type RoadPart = {
  km: number
  value: string
  unit: string
  road_type: string
  centerline: boolean
  approximate: boolean
  cite: Cite
}

/** `agrees`: figures elsewhere that agree with this one, so they aren't options: rounded ("about 300 km" for 310 km)
 * or within 2% (the same roads measured twice). */
export type RoadOption = {
  km: number
  centerline: boolean
  approximate: boolean
  why: string
  parts: RoadPart[]
  agrees?: (RoadPart & { agrees_by?: 'rounded' | 'near' })[]
}

export type Step = {
  t: string
  step: string
  msg: string
  url?: string
  to?: string
  status?: number
  bytes?: number
  ms?: number
  waited_ms?: number
  why?: string
  page?: string
  rate_rule?: string
  pdf_page?: number
  delay_s?: number
  model?: string
  /** On the check step: how many values the checks refused. */
  rejected?: number
}

export type Source = {
  id: string
  url: string
  kind: 'html' | 'pdf' | 'dataset'
  title: string
  status: number
  bytes: number
  sha256: string
  fetched_at: string
  pdf_pages_read: number[] | null
  pdf_page_count: number | null
}

/** A brief sentence that failed carries its `cites` and no source; a sign line that failed has no value. */
export type Rejection = {
  field: string
  value: string | null
  reason: string
  quote: string
  source?: string
  url?: string
  title?: string
  pdf_page?: number | null
  fetched_at?: string
  cites?: string[]
}

export type ZohoRequest = { method: string; url: string; body: { data: Record<string, unknown>[]; [k: string]: unknown } }

export type Run = {
  account: {
    slug: string
    crm_id: string
    name: string
    website: string
    jurisdiction: 'ON' | 'NY'
    region: string
    ny_county: string | null
  }
  run: {
    started_at: string
    finished_at: string
    model: string
    pages_read: number
    page_fetches: number
    page_budget: number
    http_requests: number
    /** Characters of page text sent to the model in the extract call. */
    prompt_chars: number
  }
  status: 'done' | 'needs_review'
  steps: Step[]
  sources: Source[]
  fetch_errors: { url: string; reason: string }[]
  validated: {
    road_length_km: {
      options: RoadOption[]
      status: string
      value_km?: number
      within_km?: number
      within_mi?: number
      data_year?: string
    }
    /** `values`: every number the pages print for the department, when they disagree. */
    phone: { status: string; value?: string; values?: string[] }
  }
  rejected: Rejection[]
  proposed: ProposedRow[]
  questions: Question[]
  merge: Merge | null
  /** Lines about sign work that passed the checks: what the brief may quote, with the PDF page each sits on. */
  sign_work: Pick<Cite, 'quote' | 'source' | 'pdf_page'>[]
  brief: { sentences: { text: string; cites: string[] }[]; model: string | null; skipped?: string }
  writeback: { sent: boolean; note: string; requests: ZohoRequest[] }
}

export type Meta = {
  run_date: string
  started_at: string
  finished_at: string
  model: string
  pipeline_commit: string
  answer_key_commit: string
  user_agent: string
  page_budget: number
  min_delay_s: number
  tests: { passed: number; failed: number; summary: string; network: string }
}

export type ScoreOutcome = 'right' | 'wrong' | 'correctly_blank' | 'missed' | 'sent_to_person'
export type ScoreRow = {
  outcome: ScoreOutcome
  account: string
  field: string
  got: unknown
  expected: unknown
  why?: string
  key_agrees_unclear?: boolean
  key_expect?: string | null
}

export type Scorecard = {
  answer_key_commit: string
  counts: Record<ScoreOutcome, number>
  sent_to_person_key_agrees: number
  total: number
  misses: ScoreRow[]
  rows: ScoreRow[]
}

export type SeedAccount = { crm_id: string; slug: string; Account_Type: string; Enrichment_Status: string; mock: boolean }
export type SeedContact = { mock: boolean; id: string; account: string; name: string; title: string; phone: string; email: string | null }

/** The answer key's road row: what it expects and which figures it accepts. */
export type KeyRoad = { expect: 'filled' | 'needs_human' | 'blank'; accepted_options_km?: number[]; why?: string }
export type AnswerKey = { accounts: Record<string, { road_length_km: KeyRoad }> }

export const runs: Run[] = [lincoln, pelham, westLincoln, saratoga, warren, tompkins] as unknown as Run[]
export const runBySlug: Record<string, Run> = Object.fromEntries(runs.map((r) => [r.account.slug, r]))
export const meta = metaJson as unknown as Meta
export const scorecard = scorecardJson as unknown as Scorecard
export const seed = seedJson as unknown as { label: string; accounts: SeedAccount[]; contacts: SeedContact[] }
export const answerKey = keyJson as unknown as AnswerKey
export const seedBySlug: Record<string, SeedAccount> = Object.fromEntries(seed.accounts.map((a) => [a.slug, a]))

export const REPO = 'https://github.com/PohTeyToe/riipen-waysights'

/** The Account the page opens on: the New York county with the clearest owned-or-every-road question. */
export const HERO = 'tompkins'

const MI_KM = 1.609344

/** A county's two road figures in whole km, each rounded once from its source. The stored km are
 * already rounded to 0.1, so rounding them again can be off by one: 1,975.45 km became 1,976. */
export function wholeRoadKm(run: Run): { owned: number; within: number } {
  const s = run.validated.road_length_km
  const parts = s.options[0]?.parts ?? []
  return {
    owned: Math.round(parts.length ? parts.reduce((n, p) => n + p.km, 0) : (s.value_km ?? 0)),
    within: Math.round(s.within_mi != null ? s.within_mi * MI_KM : (s.within_km ?? 0)),
  }
}

/** The Account list: the lead county first, then New York, then Niagara. */
export const listOrder: Run[] = ['tompkins', 'warren', 'saratoga', 'lincoln', 'pelham', 'west-lincoln'].map((s) => runBySlug[s])

// Short labels for the Account list and the scorecard.
export const shortName: Record<string, string> = {
  lincoln: 'Lincoln',
  pelham: 'Pelham',
  'west-lincoln': 'West Lincoln',
  saratoga: 'Saratoga',
  warren: 'Warren',
  tompkins: 'Tompkins',
}

export function isCite(s: Cite | DocLink): s is Cite {
  return 'quote' in s
}

/** A source the run read for this Account. */
export function sourceById(run: Run, id: string): Source | undefined {
  return run.sources.find((x) => x.id === id)
}

/** The NYSDOT dataset's own page, for people; the run's exact query stays in the log and the saved rows. */
export const DATASET_PAGE = 'https://data.ny.gov/Transportation/Highway-Mileage-Beginning-2008/tccz-tc3t'

/** Where a link to a source should go: the dataset's readable page instead of its raw API query. */
export function readableUrl(url: string): string {
  return url.startsWith('https://data.ny.gov/resource/tccz-tc3t') ? DATASET_PAGE : url
}
